"""Eldmark sword textures, generated by code (no photos or hand painting).

Used by tools/blender/build_sword.py (inside Blender) and can also be run standalone with
Python 3 and numpy to view the textures without opening Blender:

    python tools/blender/sword_textures.py build/sword/tex

Each texture is an 8-bit RGBA image. The color ones (albedo) are in sRGB and the
metal/roughness ones in linear, packed as glTF requires: G = roughness, B = metallic (R = 1, no
occlusion). The matrices are computed with row 0 at the BOTTOM of the image (v = 0 in
Blender); they are flipped when the PNG is saved.

Textures:
- blade (256 x 512), one per variant (`blade_<variante>_albedo`, `_mr` and, only Askarra's,
  `_emit`): u = position across the section's width (0 = left edge, 1 = right edge, fixed for
  any blade width), v = distance along (0 = pommel, 1 = tip). It marks the edge as a thin
  light band, the faces and the major bevel in a cold, dark steel gray, and the fuller,
  which in each realm carries its own thing: ice runes (Vardheim), inlaid gold (Solmarch) or a flaming
  crack (Askarra). The contrast comes from a dark albedo with a light edge, not from a light one
  top to bottom: a light steel blends in with the gray sky.
- leather (256 x 256): u = wrap around the grip, v = phase of the leather wrap (one
  full wrap per unit). It has the shadow between wraps and the stitches drawn in.
- metal (256 x 384, atlas in three strips): at the bottom the main metal (guard, pommel, rings), in the middle
  the accent (stones, rivets, inlays) and at the top the polished edge, lighter and smoother, used
  by the bevel faces so that each piece's border catches the light.
"""

import os
import struct
import sys
import zlib

import numpy as np

# Palettes by realm, in sRGB from 0 to 1. "metal" and "accent" are the base color of the main metal and
# of the secondary one; metallic and roughness go separately. The colors are low on purpose: a
# light, smooth metal looks like pastel plastic; the shine comes from the edges and the sky's reflection.
PALETTES = {
	"base": {
		"leather": (0.36, 0.21, 0.11), "thread": (0.80, 0.67, 0.46),
		"metal": (0.50, 0.53, 0.58), "metal_rough": 0.34, "metal_metallic": 0.85,
		"accent": (0.86, 0.62, 0.22), "accent_metal": 0.9, "accent_rough": 0.30,
	},
	"vardheim": {
		"leather": (0.10, 0.15, 0.28), "thread": (0.62, 0.80, 0.94),
		"metal": (0.42, 0.52, 0.70), "metal_rough": 0.34, "metal_metallic": 0.85,
		"accent": (0.30, 0.66, 0.92), "accent_metal": 0.15, "accent_rough": 0.38,
	},
	"solmarch": {
		"leather": (0.86, 0.83, 0.75), "thread": (0.86, 0.64, 0.20),
		"metal": (0.92, 0.62, 0.16), "metal_rough": 0.24, "metal_metallic": 0.94,
		"accent": (0.96, 0.50, 0.10), "accent_metal": 0.10, "accent_rough": 0.34,
	},
	"askarra": {
		"leather": (0.52, 0.07, 0.09), "thread": (0.84, 0.54, 0.26),
		# Real bronze, not wood: lighter and more yellow, with less metallic (a dark, highly reflective metal reads
		# as matte brown in hand) and shine on the edge.
		"metal": (0.90, 0.64, 0.27), "metal_rough": 0.27, "metal_metallic": 0.62,
		"accent": (0.24, 0.22, 0.22), "accent_metal": 0.90, "accent_rough": 0.40,
	},
}

# Blade section: where (as a fraction of the half width, 0 = axis, 1 = edge) each break falls.
# build_sword.py uses the same numbers to model the blade, so the painted highlight matches.
S_FULLER_FLOOR = 0.18
S_FULLER_RIM = 0.30
S_SHOULDER = 0.50
S_BEVEL = 0.76

# Where the fuller starts and ends along the blade (in meters from the grip's center;
# build_sword.py uses the same numbers) and the blade's length.
FULLER_START = (0.185, 0.265)
FULLER_END = (0.66, 0.80)
TIP_Z = 0.94

# Metal atlas: three equal strips in v. At the bottom, the main metal; in the middle, the accent; at the top,
# the polished edge.
ATLAS_BANDS = 3

# What each blade carries. "tint" multiplies the steel gray of the faces, "edge" that of the edge, and "dark"
# scales the tone of the faces (Askarra is blackened steel).
BLADE_STYLES = {
	# Base: light steel with little metallic. With 0.88 the blade reflected the overcast sky and the valley's shadow and came out
	# almost black in hand; with 0.45 it keeps the mid-steel albedo and the edge still shines.
	"base": {"tint": (0.94, 0.97, 1.00), "edge": (0.98, 0.99, 1.00), "dark": 1.00, "metal": 0.45,
			"face": 0.74, "bevel": 0.76},
	"vardheim": {"tint": (0.86, 0.94, 1.00), "edge": (0.92, 0.98, 1.00), "dark": 1.00, "metal": 0.62,
			"face": 0.72, "bevel": 0.74},
	# Solmarch: warm pearl white on the faces (the gold goes in the fuller), with less metallic so that it
	# does not reflect the gray sky and go dull.
	"solmarch": {"tint": (1.00, 0.97, 0.89), "edge": (1.00, 0.98, 0.90), "dark": 1.00, "metal": 0.80,
			"face": 0.84, "bevel": 0.86},
	"askarra": {"tint": (0.95, 0.90, 0.88), "edge": (1.00, 0.84, 0.68), "dark": 0.62, "metal": 0.80},
}
# Tone (sRGB albedo) of each zone of the section, from the axis to the edge. The faces and the major bevel are
# a mid steel (0.62 to 0.68: darker reads as obsidian from the game camera); the edge is
# light and measures 2-3 px wide at that distance.
TONE_FULLER = 0.32
TONE_FULLER_WALL = (0.38, 0.52)
TONE_FACE = 0.65
TONE_BEVEL = 0.67
TONE_EDGE = 0.98
# Emission of Askarra's crack (multiplied by the material's strength in the GLB).
EMBER_COLOR = (1.00, 0.30, 0.04)


def wrap_profile(p):
	"""Profile of one leather wrap, p in [0, 1): 0 in the valley between wraps and 1 at the ridge.

	It rises slowly to the ridge (near p = 0.75) and drops faster toward the valley, like a strip
	of leather that overlaps the previous one. Geometry and texture share it so the painted
	shadow falls exactly in the modeled gap.
	"""
	p = np.asarray(p, dtype=np.float64) % 1.0
	rise = np.clip(p / 0.75, 0.0, 1.0)
	fall = np.clip((1.0 - p) / 0.25, 0.0, 1.0)
	up = np.sin(rise * np.pi * 0.5) ** 0.9
	down = np.sin(fall * np.pi * 0.5) ** 1.3
	return np.where(p < 0.75, up, down)


def grid(width, height):
	"""(u, v) coordinates of each pixel's center; row 0 is v ≈ 0."""
	u = (np.arange(width) + 0.5) / width
	v = (np.arange(height) + 0.5) / height
	return np.meshgrid(u, v)


def fft_noise(width, height, cutoff_u, cutoff_v, seed):
	"""Seamlessly repeating noise, from roughly -1 to 1.

	cutoff_u and cutoff_v are cycles per texture: low values give large blotches, high ones give grain.
	"""
	rng = np.random.default_rng(seed)
	spectrum = np.fft.fft2(rng.standard_normal((height, width)))
	ky = np.fft.fftfreq(height)[:, None] * height
	kx = np.fft.fftfreq(width)[None, :] * width
	spectrum *= np.exp(-((kx / cutoff_u) ** 2 + (ky / cutoff_v) ** 2))
	out = np.real(np.fft.ifft2(spectrum))
	out /= max(float(out.std()) * 3.0, 1e-9)
	return np.clip(out, -1.0, 1.0)


def _smooth(edge0, edge1, x):
	t = np.clip((x - edge0) / (edge1 - edge0), 0.0, 1.0)
	return t * t * (3.0 - 2.0 * t)


def _pack(color, rough, metal):
	"""Stacks albedo (sRGB) and metal/roughness (linear) into two 8-bit RGBA images."""
	height, width = rough.shape
	albedo = np.concatenate([np.clip(color, 0.0, 1.0), np.ones((height, width, 1))], axis=2)
	mr = np.stack([np.ones_like(rough), np.clip(rough, 0.0, 1.0), np.clip(metal, 0.0, 1.0),
			np.ones_like(rough)], axis=2)
	return (albedo * 255.0 + 0.5).astype(np.uint8), (mr * 255.0 + 0.5).astype(np.uint8)


def fuller_mask(v):
	"""How much fuller there is at each point along (0 to 1), just like the blade's geometry."""
	return _smooth(FULLER_START[0] / TIP_Z, FULLER_START[1] / TIP_Z, v) \
			* (1.0 - _smooth(FULLER_END[0] / TIP_Z, FULLER_END[1] / TIP_Z, v))


def fuller_width_scale(v):
	"""How wide the fuller is at each point along (from 0.35 to 1), just like the geometry.

	It starts and ends in an ogive: narrow at the tip of each end and widening quickly to its full
	width (the ^0.6 curve opens fast and flattens, like a pointed arch), not in a rectangular step.
	"""
	return 0.35 + 0.65 * np.asarray(fuller_mask(v), dtype=np.float64) ** 0.6


def _segment_distance(px, py, ax, ay, bx, by):
	"""Distance from each point (px, py) to the segment from (ax, ay) to (bx, by)."""
	dx, dy = bx - ax, by - ay
	t = np.clip(((px - ax) * dx + (py - ay) * dy) / max(dx * dx + dy * dy, 1e-12), 0.0, 1.0)
	return np.hypot(px - (ax + t * dx), py - (ay + t * dy))


# Runes: each one is strokes (x0, y0, x1, y1) with x in units of s (from -1 to 1 across the
# blade's width) and y in fractions of the cell.
RUNE_PATTERNS = [
	[(0.0, 0.10, 0.0, 0.90), (-0.07, 0.30, 0.0, 0.52), (0.07, 0.64, 0.0, 0.42)],
	[(0.0, 0.10, 0.0, 0.90), (0.07, 0.22, 0.0, 0.50), (-0.07, 0.78, 0.0, 0.52)],
	[(0.0, 0.10, 0.0, 0.90), (-0.07, 0.50, 0.07, 0.30), (0.07, 0.50, -0.07, 0.30)],
	[(-0.05, 0.12, -0.05, 0.88), (0.05, 0.12, 0.05, 0.88), (-0.05, 0.50, 0.05, 0.50)],
]


def runes(s_signed, v, v0, v1, cell=0.045, aspect=0.18):
	"""A row of runes along the fuller, from 0 to 1.

	Each cell of length `cell` (in v) carries a rune from RUNE_PATTERNS according to its number; `aspect`
	is what the cell measures in units of s, so the strokes do not come out stretched.
	"""
	index = np.floor((v - v0) / cell)
	local = (v - v0) / cell - index
	inside = ((v >= v0) & (v <= v1)).astype(np.float64)
	mask = np.zeros_like(v)
	for number, strokes in enumerate(RUNE_PATTERNS):
		which = (np.mod(index, len(RUNE_PATTERNS)) == number)
		distance = np.full_like(v, 9.0)
		for x0, y0, x1, y1 in strokes:
			distance = np.minimum(distance, _segment_distance(
					s_signed, local * aspect, x0, y0 * aspect, x1, y1 * aspect))
		mask = np.where(which, np.exp(-((distance / 0.011) ** 2)), mask)
	return mask * inside


def _crack_path(v):
	"""Position across the width (in units of s) of Askarra's crack at each v: a soft zigzag."""
	path = 0.050 * np.sin(v * 41.0) + 0.032 * np.sin(v * 97.0 + 1.7) + 0.020 * np.sin(v * 213.0 + 0.4)
	return np.clip(path, -0.10, 0.10)


def blade_textures(palette="base", width=256, height=512):
	"""Dark steel with a light edge, gradient along the length and each realm's own fuller.

	Returns (albedo, metal/roughness) and, only with `palette == "askarra"`, the emission texture as the
	third element (the flaming crack of the fuller).
	"""
	style = BLADE_STYLES[palette]
	u, v = grid(width, height)
	s_signed = 2.0 * u - 1.0
	s = np.abs(s_signed)  # 0 at the axis, 1 at the edge
	ff, rim, sh, bev = S_FULLER_FLOOR, S_FULLER_RIM, S_SHOULDER, S_BEVEL
	groove = fuller_mask(v)
	# The fuller starts and ends in an ogive: its width grows with v (see fuller_width_scale), so its
	# breaks (floor and edge) are measured with s_eff = s / width and not with s.
	s_eff = s / fuller_width_scale(v)
	face_tone = style.get("face", TONE_FACE)
	bevel_tone = style.get("bevel", TONE_BEVEL)
	# Tone per zone of the section (see build_sword.py): fuller (only where there is one), flat face,
	# major bevel and edge. The transitions are short but not one pixel, so they do not flicker.
	stops_g = [0.0, ff - 0.015, ff + 0.012, rim, rim + 0.012]
	groove_tone = np.interp(s_eff, stops_g, [TONE_FULLER, TONE_FULLER, TONE_FULLER_WALL[0],
			TONE_FULLER_WALL[1], face_tone])
	stops_s = [0.0, sh - 0.012, sh + 0.012, bev - 0.012, bev + 0.014, 1.0]
	flat_tone = np.interp(s, stops_s, [face_tone, face_tone, bevel_tone, bevel_tone, TONE_EDGE, TONE_EDGE])
	# The fuller only governs within its width (outside, np.interp would keep the face's tone).
	in_groove = groove * (1.0 - _smooth(rim + 0.002, rim + 0.014, s_eff))
	tone = flat_tone + (groove_tone - flat_tone) * in_groove
	is_edge = _smooth(bev - 0.012, bev + 0.014, s)
	# Gradient along the length: darker next to the guard (x0.75) and lighter toward the tip. The edge
	# barely changes: it has to be light from end to end.
	along = _smooth(0.05, 0.95, v)
	body_gain = (0.90 + 0.12 * along) * style["dark"]
	edge_gain = (0.97 + 0.03 * along) * (0.94 if palette == "askarra" else 1.0)
	tone = tone * (body_gain * (1.0 - is_edge) + edge_gain * is_edge)
	# Ricasso (next to the guard, no edge): a hair more opaque, and the shadow the guard casts.
	ricasso = 1.0 - _smooth(0.14, 0.22, v)
	tone = tone * (1.0 - 0.06 * ricasso)
	tone = tone * (1.0 - 0.28 * np.exp(-(((v - 0.133) / 0.025) ** 2)) * (1.0 - is_edge))
	# A thin highlight on the fuller's border and on the major bevel's shoulder, so that the
	# steel has relief even when dark.
	rim_line = np.exp(-(((s_eff - rim) / 0.011) ** 2)) * groove * 0.12
	shoulder_line = np.exp(-(((s - sh) / 0.012) ** 2)) * 0.07
	tone = tone + (rim_line + shoulder_line) * (1.0 - is_edge)
	# Polish: an almost invisible fine grain and very faint streaks along the blade (with more amplitude, next to the
	# ricasso they look like stretched vertical streaks).
	brushed = fft_noise(width, height, 70.0, 4.0, 11)
	grain = fft_noise(width, height, 100.0, 100.0, 12)
	tone = tone + brushed * 0.003 + grain * 0.006
	# Tip somewhat livelier.
	tone = tone + 0.04 * _smooth(0.90, 0.99, v) * (1.0 - is_edge)
	tint = np.array(style["tint"])[None, None, :] * (1.0 - is_edge[..., None]) \
			+ np.array(style["edge"])[None, None, :] * is_edge[..., None]
	color = np.clip(tone[..., None] * tint, 0.0, 1.0)
	# Roughness and metallic by zone: polished steel (roughness 0.30 to 0.35, metallic 0.85 to 0.90). The bottom of
	# the fuller is somewhat rougher so it does not give a reflection hot spot.
	stops_r = [0.00, sh + 0.015, bev - 0.015, bev + 0.015, 1.00]
	rough_flat = np.interp(s, stops_r, [0.34, 0.33, 0.32, 0.24, 0.22])
	rough_groove = np.interp(s_eff, [0.0, ff - 0.015, ff + 0.01, rim + 0.015],
			[0.50, 0.50, 0.46, 0.34])
	rough = rough_flat + (rough_groove - rough_flat) * groove * (s_eff < rim + 0.015) + brushed * 0.012
	metal = np.full_like(rough, style["metal"])
	emit = None
	in_fuller = groove * (1.0 - _smooth(rim - 0.05, rim, s_eff))
	if palette == "vardheim":
		# Blue ice in the fuller and a row of white runes down the middle.
		ice = np.array([0.14, 0.40, 0.66])[None, None, :] * (0.85 + 0.30 * along)[..., None]
		color = color * (1.0 - in_fuller[..., None]) + ice * in_fuller[..., None]
		marks = runes(s_signed, v, 0.30, 0.68) * in_fuller
		color = color * (1.0 - marks[..., None]) + np.array([0.94, 0.99, 1.0])[None, None, :] * marks[..., None]
		rough = rough + (0.42 - rough) * in_fuller
		metal = metal + (0.35 - metal) * in_fuller
	elif palette == "solmarch":
		# Gold inlaid in the fuller, with a ribbon of darker diamonds.
		gold = np.array([0.88, 0.63, 0.21])[None, None, :]
		color = color * (1.0 - in_fuller[..., None]) + gold * in_fuller[..., None]
		diamond = np.abs(np.mod(v / 0.05, 1.0) - 0.5) * 2.0 + np.abs(s_signed) * 4.5
		band = _smooth(0.28, 0.30, v) * (1.0 - _smooth(0.66, 0.68, v))
		pattern = (diamond < 0.9).astype(np.float64) * band * in_fuller
		color = color * (1.0 - 0.30 * pattern[..., None])
		rough = rough + (0.40 - rough) * in_fuller
		metal = metal + (0.90 - metal) * in_fuller
	elif palette == "askarra":
		# Blackened, matte steel, and the flaming crack that runs along the fuller.
		rough = rough + 0.14
		metal = np.full_like(rough, 0.72)
		distance = np.abs(s_signed - _crack_path(v))
		gaps = fft_noise(width, height, 1.0, 9.0, 41)[:, :1]  # breaks along the length, equal across the width
		live = _smooth(-0.55, -0.10, gaps)
		bell = np.sin(np.pi * np.clip((v - 0.20) / 0.66, 0.0, 1.0)) ** 0.6
		core = np.clip(1.6 * np.exp(-((distance / 0.034) ** 2)), 0.0, 1.0) * bell * (0.50 + 0.50 * live)
		glow = np.exp(-((distance / 0.10) ** 2)) * bell * 0.38
		# Branches that leave the crack toward the shoulder: a fracture, not a stripe.
		for v_a, v_b, side in ((0.34, 0.41, 1.0), (0.52, 0.45, -1.0), (0.62, 0.69, 1.0)):
			centre = float(_crack_path(np.array(v_a)))
			branch = _segment_distance(s_signed, v, centre, v_a, side * 0.20, v_b)
			core = core + np.clip(1.6 * np.exp(-((branch / 0.022) ** 2)), 0.0, 1.0) * 0.85
		heat = np.clip(core + glow, 0.0, 1.0) * groove * (1.0 - _smooth(rim, rim + 0.05, s_eff))
		red, green, blue = EMBER_COLOR
		emission = np.stack([heat * red, (heat ** 1.4) * green, (heat ** 2.5) * blue,
				np.ones_like(heat)], axis=2)
		emit = (np.clip(emission, 0.0, 1.0) * 255.0 + 0.5).astype(np.uint8)
		soot = np.array([0.045, 0.03, 0.03])[None, None, :]
		color = color * (1.0 - 0.75 * in_fuller[..., None]) + soot * 0.75 * in_fuller[..., None]
		# The open fracture is lava: its own dark-reddish albedo, with no specular shine.
		color = color * (1.0 - 0.6 * heat[..., None]) + np.array([0.30, 0.05, 0.02])[None, None, :] \
				* 0.6 * heat[..., None]
		rough = rough + (0.85 - rough) * heat
	# A thin finishing notch on the edge, near the ricasso.
	mark = np.exp(-(((v - 0.205) / 0.006) ** 2)) * (s < 0.95)
	color = color * (1.0 - 0.18 * mark[..., None])
	albedo, mr = _pack(color, rough, metal)
	if emit is None:
		return albedo, mr
	return albedo, mr, emit


def leather_textures(palette, width=256, height=256):
	"""Leather with one wrap per unit of v: shadow between wraps, grain and stitches."""
	u, v = grid(width, height)
	base = np.array(PALETTES[palette]["leather"])
	thread = np.array(PALETTES[palette]["thread"])
	profile = wrap_profile(v)
	occlusion = 0.42 + 0.58 * profile ** 0.8
	# Ridge light: raises the color a little where the strip is highest.
	shade = occlusion * (0.88 + 0.16 * profile)
	grain = fft_noise(width, height, 80.0, 80.0, 21) * 0.07
	mottling = fft_noise(width, height, 7.0, 5.0, 22) * 0.10
	# Leather wrinkles: thin and almost parallel to the wrap.
	wrinkle = fft_noise(width, height, 36.0, 6.0, 23) * 0.05
	color = base[None, None, :] * (shade * (1.0 + grain + mottling + wrinkle))[..., None]
	# Stitches: alternating strokes next to the valley (v ≈ 0.06).
	dash = (np.floor(u * 24.0) % 2 == 0).astype(np.float64)
	stitch_band = np.exp(-(((v - 0.07) / 0.022) ** 2))
	stitch = stitch_band * (0.55 + 0.45 * dash) * 0.85
	color = color * (1.0 - stitch[..., None]) + thread[None, None, :] * stitch[..., None] * 0.9
	# Leather edge somewhat lighter (wear) at the ridge.
	edge = np.exp(-(((v - 0.76) / 0.05) ** 2)) * 0.10
	color = color + edge[..., None] * 0.35
	rough = 0.74 + fft_noise(width, height, 40.0, 40.0, 24) * 0.10 - 0.08 * profile
	metal = np.zeros_like(rough)
	return _pack(color, rough, metal)


def metal_textures(palette, width=256, height=384):
	"""Metal atlas in three strips: the main one at the bottom, the accent in the middle, the polished edge at the top."""
	u, v = grid(width, height)
	spec = PALETTES[palette]
	main = np.array(spec["metal"])
	accent = np.array(spec["accent"])
	# The edge: the same metal, much lighter and smoother, as if burnished by use. The highest
	# channel is raised to almost 1 and a quarter of white is mixed in, without changing the hue (otherwise the gold
	# turns greenish yellow).
	polished = main / max(float(main.max()), 1e-6) * 0.98 * 0.75 + 0.25
	brushed = fft_noise(width, height, 3.0, 80.0, 31)
	grain = fft_noise(width, height, 90.0, 90.0, 32)
	blotch = fft_noise(width, height, 5.0, 5.0, 33)
	variation = 1.0 + brushed * 0.04 + grain * 0.02 + blotch * 0.06
	band = np.minimum((v * ATLAS_BANDS).astype(int), ATLAS_BANDS - 1)
	top = band == 2
	mid = band == 1
	base_color = np.where(top[..., None], polished[None, None, :],
			np.where(mid[..., None], accent[None, None, :], main[None, None, :]))
	color = base_color * variation[..., None]
	# A soft gradient along each strip (darker at the bottom, lighter at the top): the large flat
	# faces of the guard and the pommel do not end up a flat color and have some volume. The
	# box mapping leaves v growing with the piece's height.
	within = (v * ATLAS_BANDS) % 1.0
	color = color * (0.86 + 0.24 * np.clip(within, 0.0, 1.0))[..., None]
	rough = np.where(top, spec["metal_rough"] * 0.70, np.where(mid, spec["accent_rough"], spec["metal_rough"]))
	rough = rough + blotch * 0.05 + grain * 0.03
	metal = np.where(mid, spec["accent_metal"], spec["metal_metallic"]) + np.zeros_like(rough)
	return _pack(color, rough, metal)


def write_png(path, rgba):
	"""Saves a uint8 RGBA (row 0 = bottom) as a PNG without dependencies."""
	data = np.flipud(rgba)
	height, width, channels = data.shape
	raw = b"".join(b"\x00" + data[row].tobytes() for row in range(height))

	def chunk(kind, payload):
		body = kind + payload
		return struct.pack(">I", len(payload)) + body + struct.pack(">I", zlib.crc32(body) & 0xFFFFFFFF)

	color_type = {3: 2, 4: 6}[channels]
	header = struct.pack(">IIBBBBB", width, height, 8, color_type, 0, 0, 0)
	png = b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", header) + chunk(b"IDAT", zlib.compress(raw, 9)) \
			+ chunk(b"IEND", b"")
	with open(path, "wb") as handle:
		handle.write(png)


def write_all(out_dir):
	"""Writes all the textures to out_dir and returns {name: path}."""
	os.makedirs(out_dir, exist_ok=True)
	paths = {}

	def save(name, images):
		for suffix, image in zip(("albedo", "mr", "emit"), images):
			path = os.path.join(out_dir, "%s_%s.png" % (name, suffix))
			write_png(path, image)
			paths["%s_%s" % (name, suffix)] = path

	for palette in PALETTES:
		save("blade_" + palette, blade_textures(palette))
		save("leather_" + palette, leather_textures(palette))
		save("metal_" + palette, metal_textures(palette))
	return paths


if __name__ == "__main__":
	target = sys.argv[1] if len(sys.argv) > 1 else "build/sword/tex"
	for key, value in write_all(target).items():
		print(key, value)
